using System;using System.IO;using System.Linq;using System.Collections;using UnityEngine;using UnityEditor;
public static class MotionWork{public static void Run(){new GameObject("Roach frame probe").AddComponent<RoachFrameProbe>();}}
public class RoachFrameProbe:MonoBehaviour{IEnumerator Start(){const string W="C:/UnityProjects/LegacyGwent/work/DynamicCards/MotionIntegrity/ScrollAndFramingRepair/";var model=Instantiate(AssetDatabase.LoadAssetAtPath<GameObject>("Assets/DynamicCards/Content/Old/Legacy2017/11221001/Card.prefab"));model.transform.position=new Vector3(500,500,0);model.SetActive(true);foreach(Transform t in model.transform){if(t.localPosition.sqrMagnitude>1000000)t.localPosition=Vector3.zero;if(Quaternion.Angle(t.localRotation,Quaternion.Euler(0,180,0))<.01)t.localRotation=Quaternion.identity;}foreach(var a in model.GetComponentsInChildren<Animator>(true))a.enabled=false;var pivot=model.transform.Find("11221001/Pivot");var clip=AssetDatabase.LoadAssetAtPath<AnimationClip>("Assets/DynamicCards/Content/Old/Legacy2017/11221001/Source_faf670a8_Roach_Loop_Effect.anim");var c=new GameObject("Roach probe camera").AddComponent<Camera>();c.enabled=false;c.transform.position=model.transform.position+new Vector3(0,0,-29.87103f);c.fieldOfView=25;c.nearClipPlane=1;c.farClipPlane=450;c.aspect=1;c.clearFlags=CameraClearFlags.SolidColor;c.backgroundColor=Color.clear;c.allowHDR=false;var rt=new RenderTexture(1024,1024,24);c.targetTexture=rt;var rows=new System.Collections.Generic.List<string>();for(int i=0;i<=20;i+=4){clip.SampleAnimation(pivot.gameObject,i);yield return null;c.Render();var previous=RenderTexture.active;RenderTexture.active=rt;var image=new Texture2D(1024,1024,TextureFormat.RGBA32,false);image.ReadPixels(new Rect(0,0,1024,1024),0,0);image.Apply();File.WriteAllBytes(W+"roach-source-pose-"+i+".png",image.EncodeToPNG());Destroy(image);RenderTexture.active=previous;foreach(var t in model.GetComponentsInChildren<Transform>(true).Where(t=>t.name.Contains("Roach_Body_Root")||t.name.Contains("Roach_Head")))rows.Add(i+" "+t.name+" local="+t.localPosition+" worldRelative="+model.transform.InverseTransformPoint(t.position)+" viewport="+c.WorldToViewportPoint(t.position));}File.WriteAllLines(W+"roach-source-positions.txt",rows);Destroy(model);Destroy(c.gameObject);rt.Release();Destroy(rt);Destroy(gameObject);}}
